
SELECT 
	EVNT.CRDDET_ID						AS	CRD_KEY
	--,EVNT.EVDATETIME 					AS	EVNT_DTTM
,from_unixtime(CAST(CAST(EVNT.EVDATETIME AS BIGINT) / 1000 AS BIGINT)) 	AS	EVNT_DTTM	
	,EVNT.EVTYPE						AS	EVNT_TYP_CD	
	,TYP.DESCR							AS	EVNT_TYP
	,EVNT.REASON						AS	EVNT_RSN	
	,EVNT.EVSRC							AS	EVNT_SRC_CD
	,SRC.DESCR							AS	EVNT_SRC
	,EVNT.EVNOTES						AS	EVNT_NOTES
	,EVNT.STATUS						AS	STS
	,CASE WHEN EVNT.FEECTRL=0 THEN 'N' ELSE 'Y' END	AS	Waived_FLG
	,CURRENT_TIMESTAMP					AS	INS_DTTM
	--,CAST (EVNT.EVDATETIME	AS DATE)	AS	EVNT_DT
,to_date(from_unixtime(FLOOR(CAST(EVNT.EVDATETIME AS BIGINT) / 1000)))	AS	EVNT_DT
,cast(current_timestamp as string) as tec_insrt_dttm,
cast(current_timestamp as string) as tec_upd_dttm,
NULL as dr_dttm,		
NULL as dr_flg

FROM ${stg_schema}.CRDEVENT EVNT

LEFT JOIN ${stg_schema}.NUMDESCR SRC
	ON EVNT.EVSRC = SRC.ID
	AND SRC.DESCRTYPE = 'evsrc'
LEFT JOIN ${stg_schema}.NUMDESCR TYP
  ON EVNT.EVTYPE = TYP.ID
  AND TYP.DESCRTYPE = 'evtype'
	
--where EVNT.EVDATETIME > (CURRENT_TIMESTAMP - INTERVAL 48 HOUR)
QUALIFY row_number() over(partition by CRDDET_ID, EVTYPE order by EVNT.EVDATETIME desc) = 1

